-- Schede nuove dalle pagine RHS (controllo periodico del 23/11/2026): 24 specie del catalogo senza
-- nessuna scheda. Testi in italiano scritti a mano (scripts/rhs-import/dati/), in bozza e mostrate.
-- Generata da scripts/rhs-import/schede_nuove.py. Rollback: scripts/rhs-import/rollback_rhs_schede_nuove_lotto3.sql
do $$ begin
  if exists (select 1 from public.schede where taxon_id in ('f35b15e6-e03b-467d-aea3-88101cde08a8'::uuid, 'b1e14729-76cf-45f3-8db4-d9e7f39a9165'::uuid, 'fbd7e358-ae9e-49c1-bf1e-34f35277c516'::uuid, 'eb36ab6b-f43f-48c8-bd14-667c595cfce1'::uuid, '18db1ada-7eca-4cbd-ad81-786e51fda397'::uuid, '99e1694a-16ec-4caa-b4b0-271dc0d6e58d'::uuid, '28b34697-edb6-4996-817b-7f2e6ef79eff'::uuid, '42bda809-ada9-4e24-a86f-ba1d4463783e'::uuid, 'a3e1830c-2db8-4363-9331-2089f0675f8b'::uuid, 'a705ecc8-e956-4dd9-ac29-6b8de650282f'::uuid, 'd96b3bb5-5441-4b52-b21a-8939589a4557'::uuid, '6c8e873a-4c36-4916-a3a6-4357cf32144b'::uuid, '5d98a891-7a55-4a49-8f91-54bf3c8ce590'::uuid, '9b57e705-7d30-4ed5-b1b9-aca3bedc50fe'::uuid, '202186a4-f7e8-4220-bfa7-2ce98fa82a01'::uuid, '8bc872f2-9d42-4c3d-b71b-fe6baa36ab2f'::uuid, '7c2d48a3-f15b-4193-8161-36deb5e1c461'::uuid, '3d27e9db-88c1-430a-a9c0-09c551104595'::uuid, '5ac70761-7b92-4452-bd30-828477ca5d92'::uuid, '2f1a0839-b2c7-4250-a3cf-b4fa4744a447'::uuid, '413ed707-5ce9-4b81-b438-38e45a3cf49a'::uuid, 'b58350b9-9022-4963-a629-1e994d1553e0'::uuid, 'd0817fb9-2de6-4f46-9be9-c38ea28c33e6'::uuid, 'fe8e4333-fbba-497c-910a-e9f520684188'::uuid)) then
    raise exception 'una di queste specie ha già una scheda: lotto da rigenerare';
  end if;
end $$;
insert into public.schede (id, taxon_id, fonti, descrizione, descrizione_originale, lingua_descrizione, esigenze,
  ciclo_vitale, alert, stato_verifica, mostrata, forma, nota) values
('01c73061-273f-5ff9-8aba-3bd3d233e5c2'::uuid, 'f35b15e6-e03b-467d-aea3-88101cde08a8'::uuid, array['RHS (rhs.org.uk) — Aglaonema commutatum ''Silver Queen''']::text[], 'Perenne sempreverde della famiglia delle Aracee, originaria delle foreste delle Filippine e di Sulawesi, tra le piante d''appartamento più diffuse. Cresce eretta fino a 40-60 cm con foglie lanceolate, lucide, segnate da macchie e bande argentate o verde chiaro lungo le nervature; le numerose varietà, come ''Silver Queen'', sono quasi del tutto argentate. Fiorisce di rado in casa, con piccole spate verdastre. Sopporta la poca luce, ma non la luce solare diretta né il freddo sotto i 10 °C; le annaffiature vanno misurate perché l''acqua in eccesso fa marcire i fusti. Il succo è irritante.', 'An evergreen perennial of upright habit to 40cm in height, with handsome silvery lance-shaped leaves marbled with darker green; flowers seldom produced', 'it', '{"luce": "Mezz''ombra", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura; si tolgono le foglie ingiallite', 'Propagazione: per polloni basali o per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 704'),
('64333d5f-4bb0-5f00-9f9c-ca50c47d8c20'::uuid, 'b1e14729-76cf-45f3-8db4-d9e7f39a9165'::uuid, array['RHS (rhs.org.uk) — Begonia × hiemalis ''Elatior''']::text[], 'Begonia ibrida della famiglia delle Begoniacee, ottenuta incrociando Begonia socotrana con le begonie tuberose, nota nei negozi come begonia elatior. Forma piante cespugliose e compatte, alte fino a 30 cm, con foglie lucide verde scuro e una fioritura abbondante di fiori semplici o doppi, rossi, gialli, rosa, arancio o bianchi. In casa fiorisce in quasi tutte le stagioni, all''aperto d''estate e in autunno, dove si tratta come annuale. Vuole luce intensa ma non sole diretto, e d''inverno almeno 10 °C.', 'An evergreen, bushy perennial usually grown as a houseplant with glossy green leaves, to a height of up to 30cm. Available in red, yellow, pink, orange and white forms, it flowers throughout the year indoors and in summer and autumn when grown outdoors as an annual', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a bruchi, cocciniglie farinose, acari, tripidi, oziorrinco e afidi; Malattie: può essere soggetta a muffa grigia, oidio e marciumi del fusto e del rizoma', 'Rusticità: minime non sotto i 10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura; si tolgono i fiori appassiti', 'Propagazione: per seme a inizio primavera a 21 °C o per talee erbacee']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 84584'),
('7ce46991-3b06-5b20-bbd1-872f990f4117'::uuid, 'fbd7e358-ae9e-49c1-bf1e-34f35277c516'::uuid, array['RHS (rhs.org.uk) — Camellia × saluenensis ''Bow Bells''']::text[], 'Camelia sempreverde della famiglia delle Teacee, originaria dello Yunnan, in Cina, fitta e a crescita lenta, con foglie piccole e lucide lunghe 4-6 cm. Da metà inverno a metà primavera porta fiori semplici, piccoli, a coppa, dal rosa pallido al rosa carico, a volte bianchi. È nota soprattutto come genitrice, con Camellia japonica, delle camelie ibride × williamsii, tra le più rustiche e generose. Vuole terreno acido, una posizione riparata dai venti freddi e dal sole del primo mattino, che rovina i fiori gelati, e fiorisce bene anche in mezz''ombra.', 'A slow-growing, dense shrub with small leaves around 4-6cm long, and small, single tubular pink flowers from mid-winter to mid-spring. Flowers best when grown in full or partial shade.', 'it', '{"luce": "Ombra piena, pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi, cocciniglie e oziorrinco; Malattie: può essere soggetta a marciume radicale da Phytophthora, galle e maculature fogliari, virosi, avvizzimento dei petali e, raramente, armillaria', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 4-8m, diffusione 2.5-4m', 'Potatura: richiede pochi interventi: dopo la fioritura si accorciano i rami troppo lunghi e si tolgono quelli secchi o rovinati', 'Propagazione: per talee semilegnose']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 117712'),
('045ba4be-5c03-5020-bd6d-4fcc5d306c11'::uuid, 'eb36ab6b-f43f-48c8-bd14-667c595cfce1'::uuid, array['RHS (rhs.org.uk) — Carex caryophyllea ''The Beatles''']::text[], 'Carice sempreverde della famiglia delle Ciperacee, diffusa nei prati e nei pascoli aridi di quasi tutta Europa, Italia compresa, dove fiorisce tra le prime a primavera. Bassa, intorno ai 15 cm, si allarga lentamente con brevi rizomi e forma ciuffi di foglie sottili verde scuro; a inizio estate porta corte spighe bruno verdastre tra le foglie. Varietà come ''The Beatles'' formano una zazzera fitta e scompigliata. Vuole terreno fresco ma ben drenato, al sole o in mezz''ombra.', 'Slowly spreading, clump-forming, low-growing, evergreen perennial sedge, about 15cm tall, with a mop of fine, dark green leaves. Carries semi-trailing greenish-brown flower spikes, on short stems, within the foliage, during early summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: in estate si tolgono le foglie secche, pettinandole con le dita', 'Propagazione: per divisione da metà primavera a inizio estate']::text[], 'bozza', true, 'graminacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 52167'),
('8fdd5552-d1a2-5b7b-a046-482fd3ec7d3a'::uuid, '18db1ada-7eca-4cbd-ad81-786e51fda397'::uuid, array['RHS (rhs.org.uk) — Cestrum newellii hort.']::text[], 'Arbusto sempreverde della famiglia delle Solanacee, originario del Messico, vigoroso e alto fino a 3 m, con foglie lanceolate verde opaco. Dalla primavera all''estate porta all''estremità dei rami mazzetti di fiori tubolari lunghi circa 2 cm, di un cremisi brillante, seguiti da bacche porpora. La forma più coltivata è ''Newellii'', a lungo conosciuta come Cestrum newellii. Teme il gelo: nei climi miti cresce all''aperto in un angolo soleggiato e riparato, altrove va coltivato in vaso e ritirato d''inverno. Le bacche non vanno mangiate.', 'A vigorous evergreen shrub to 3m, with dull green lance-shaped leaves and clusters of bright crimson, tubular flowers 2cm long, followed by purple berries', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -5 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 1.5-2.5m', 'Potatura: a fine inverno si accorciano i rami dell''anno prima fino a pochi occhi da una struttura di rami principali, o si tagliano vicino a terra le piante danneggiate dal freddo', 'Propagazione: per seme in primavera, in contenitore in cassone freddo, o per talee erbacee in estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 209844'),
('35ff6e5e-cc9e-5348-8c38-6933bace16bb'::uuid, '99e1694a-16ec-4caa-b4b0-271dc0d6e58d'::uuid, array['RHS (rhs.org.uk) — Chrysanthemum rubellum ''Clara Curtis''']::text[], 'Crisantemo perenne della famiglia delle Asteracee, d''origine asiatica, oggi considerato da molti una forma di Chrysanthemum zawadskii. Forma cespi folti alti fino a 75 cm e, dalla fine dell''estate all''autunno, porta mazzi sciolti di capolini semplici, simili a margherite, larghi circa 6 cm, rosa con il centro giallo, come nella vecchia e diffusissima varietà ''Clara Curtis''. Vuole pieno sole e terreno ben drenato e mediamente fertile; cimato a primavera diventa più fitto e fiorito.', 'A bushy, clump-forming perennial to 75cm tall. This reliable, old cultivar produces loose sprays of single, pink flowerheads, 6cm across, with yellow centres that start off a greenish-yellow', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a minatori fogliari, mosca bianca e afidi; Malattie: può essere soggetto a muffa grigia, oidio e ruggine bianca del crisantemo', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: quando le piante sono alte 15-20 cm si cimano le punte; dopo la fioritura si tagliano gli steli a 10 cm da terra', 'Propagazione: per divisione o per talee basali']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 3786'),
('c1e631b1-f4d1-5124-b46e-a3a75e068fd9'::uuid, '28b34697-edb6-4996-817b-7f2e6ef79eff'::uuid, array['RHS (rhs.org.uk) — Corylopsis willmottiae']::text[], 'Grande arbusto deciduo della famiglia delle Amamelidacee, originario della Cina occidentale, dal portamento aperto e allargato, alto fino a 4 m. A inizio primavera, prima delle foglie, i rami nudi si coprono di grappoli penduli lunghi fino a 7 cm di fiori giallo chiaro a campanella, delicatamente profumati. Le foglie ovali e larghe, che ricordano quelle del nocciolo, spuntano talvolta sfumate di porpora. Vuole terreno acido e fresco e una mezz''ombra riparata, perché le gelate tardive possono rovinare la fioritura.', 'A large deciduous shrub of spreading, open habit, with broadly ovate leaves sometimes tinged purple when young. Flowers light yellow, in dense, drooping racemes to 7cm in length', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto ad armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 2.5-4m', 'Potatura: richiede pochi interventi: subito dopo la fioritura si tolgono solo i rami secchi, rovinati o mal disposti', 'Propagazione: per seme in contenitore in autunno, in cassone all''aperto, per talee erbacee in estate o per propaggine in autunno']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 4509'),
('0a82a1d2-9959-57b3-87eb-df6f34483f79'::uuid, '42bda809-ada9-4e24-a86f-ba1d4463783e'::uuid, array['RHS (rhs.org.uk) — Crassula atropurpurea var. arborescens']::text[], 'Succulenta arbustiva della famiglia delle Crassulacee, originaria della provincia del Capo in Sudafrica, che può superare il metro di altezza. I fusti robusti e ramificati portano foglie carnose grigio-verdi, spesso bordate di rosso e punteggiate di rosso sulla pagina superiore. Dall''autunno all''inverno può fiorire con piccoli fiori rosa a stella, che però in vaso compaiono di rado. Vuole molta luce, terriccio per cactacee, annaffiature moderate durante la crescita e scarse d''inverno, e non deve scendere sotto 1 °C.', 'A shrub-like succulent to 1m or more, with stout, branched stems and fleshy, grey-green leaves, often with red margins and red-spotted above. From autumn to winter it may produce star-shaped pink flowers, however these are rarely produced on pot plants', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato, umido ma ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie farinose, oziorrinco e afidi; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: non richiede potatura', 'Propagazione: per seme a 15 °C a inizio primavera o per talee di fusto o di foglia in primavera e in estate']::text[], 'bozza', true, 'succulenta', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 214378'),
('ce20955f-f231-5f10-8516-e0e43af88739'::uuid, 'a3e1830c-2db8-4363-9331-2089f0675f8b'::uuid, array['RHS (rhs.org.uk) — Crocus balansae ''Zwanenburg''']::text[], 'Piccolo croco della famiglia delle Iridacee, originario della Turchia occidentale, che non supera i 7-10 cm. Da un minuscolo cormo spuntano a inizio primavera foglie sottili e fiori a coppa giallo oro, sfumati o striati di bruno rossastro all''esterno; nella varietà ''Zwanenburg'' l''esterno è quasi tutto mogano. Vuole pieno sole e terreno ghiaioso, povero e ben drenato, ed è adatto ai giardini rocciosi e ai vasi.', 'A cormous perennial, to 7cm tall, with golden-yellow flowers almost completely suffused with dark reddish-brown on the outside', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: topi e uccelli possono danneggiarlo; Malattie: generalmente esente da malattie, ma i cormi possono marcire se conservati male', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0-0.1m', 'Potatura: non richiede potatura', 'Propagazione: staccando i cormi figli durante il riposo']::text[], 'bozza', true, 'bulbosa', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 29567'),
('66823349-7080-5471-9c2e-489365edcbd1'::uuid, 'a705ecc8-e956-4dd9-ac29-6b8de650282f'::uuid, array['RHS (rhs.org.uk) — Doronicum plantagineum ''Excelsum''']::text[], 'Perenne rizomatosa della famiglia delle Asteracee, originaria dell''Europa occidentale e sudoccidentale, alta fino a 60 cm. Le foglie basali, a cuore e verde brillante, accompagnano in primavera grandi capolini giallo oro, simili a margherite, larghi fino a 10 cm, tra i primi fiori gialli delle bordure. D''estate le foglie tendono a seccarsi e la pianta riposa. Vuole terreno fresco, ricco di humus, e mezz''ombra.', 'A rhizomatous perennial to 60cm with bright green, heart-shaped leaves and golden-yellow, daisy-like flowers up to 10cm across in spring', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti, ma può essere soggetto a nematodi fogliari; Malattie: può essere soggetto a maculatura fogliare, marciume radicale e oidio', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: togliendo i fiori appassiti si può avere una seconda fioritura', 'Propagazione: per divisione a inizio autunno']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 96551'),
('8668717c-87a7-5df7-bb0c-f46b2dfa79cd'::uuid, 'd96b3bb5-5441-4b52-b21a-8939589a4557'::uuid, array['RHS (rhs.org.uk) — Epimedium elongatum ''Enchantress''']::text[], 'Perenne rizomatosa sempreverde della famiglia delle Berberidacee, originaria dei boschi del Sichuan, in Cina, che forma cespi alti 25-30 cm. Le foglie sono divise in foglioline a cuore allungato, spinose sul margine, che in primavera spuntano marmorizzate di rosso bronzo e poi diventano verde vivo con le nervature rossastre. In primavera porta racemi di fiori delicati e speronati, nelle varietà coltivate lilla rosati con gli sproni bianchi. Vuole mezz''ombra, terreno fertile e ricco di humus e riparo dai venti freddi e secchi.', 'A clump-forming rhizomatous perennial 25-30cm high, evergreen, ternate leaves with narrowly heart-shaped, spiny-edged leaflets which emerge marbled and splashed dark bronze-red in spring and mature to bright green with red veins, and flowers of lavender-grey sepals, pale pink-lilac petals with white spurs and mouths edged with purple, and prominent yellow stamens, in spring; Epimedium leaves may be used for their nests by leaf-cutting bees', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a oziorrinco; Malattie: può essere soggetta a virosi del mosaico e maculature fogliari', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura, ma a fine inverno, prima che spuntino i fiori, si possono tagliare le foglie vecchie perché fiori e foglie nuove si vedano meglio', 'Propagazione: per divisione in autunno o dopo la fioritura, oppure per talee di rizoma tenute al riparo d''inverno']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 116857'),
('1a988302-c2bc-509f-9b3f-1fbca52304e8'::uuid, '6c8e873a-4c36-4916-a3a6-4357cf32144b'::uuid, array['RHS (rhs.org.uk) — Eranthis × tubergenii ''Guinea Gold''']::text[], 'Ibrido della famiglia delle Ranuncolacee tra l''aconito d''inverno (Eranthis hyemalis) ed Eranthis cilicica, ottenuto in Olanda nel Novecento. Da un piccolo tubero spunta a fine inverno, alto meno di 10 cm, con fiori a coppa giallo vivo, larghi 3-4 cm, circondati da un collare di brattee fogliose; le foglie basali sono lobate e verde bronzo. Essendo sterile non produce semi e i fiori durano più a lungo. Vuole terreno ricco di humus che non si secchi, meglio se calcareo, e sta bene sotto gli alberi decidui.', 'A tuberous-rooted perennial to 10cm in height, with cup-shaped bright yellow flowers 3-4cm in width, surrounded by divided leafy bracts. Basal leaves bronze-green, divided into several lobes', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a limacce; Malattie: può essere soggetto a carbone', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0-0.1m', 'Potatura: non richiede potatura', 'Propagazione: per divisione dei tuberi a fine primavera, dopo la fioritura; i tuberi seccati attecchiscono male']::text[], 'bozza', true, 'bulbosa', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 32116'),
('5c1086c0-9675-5487-98ef-5a653e2c091f'::uuid, '5d98a891-7a55-4a49-8f91-54bf3c8ce590'::uuid, array['RHS (rhs.org.uk) — Incarvillea mairei ''Bees'' Pink''']::text[], 'Perenne erbacea della famiglia delle Bignoniacee, originaria delle montagne della Cina occidentale e dell''Himalaya, conosciuta anche come gloxinia rustica per la forma dei suoi fiori. Da una robusta radice carnosa nasce una rosetta di foglie pennate, divise in foglioline grossolanamente dentate. All''inizio dell''estate, su steli eretti di circa 40 cm, porta grappoli di fiori vistosi a tromba, rosa porpora con la gola gialla. Vuole terreno fertile, fresco ma ben drenato, sole con un po'' d''ombra nelle ore calde, e teme l''umidità invernale.', 'A herbaceous perennial to around 40cm high, with a basal rosette of pinnate leaves divided into pairs of coarsely toothed leaflets. Clusters of showy, tubular to funnel-shaped pale pink flowers with yellow throats are produced on upright stems in early and mid summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a limacce; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: si tagliano gli steli sfioriti', 'Propagazione: per seme o per talee basali in primavera; le piante nate da seme possono impiegare fino a tre anni per fiorire']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 24731'),
('7f567e50-4060-5a29-a415-a83215211e08'::uuid, '9b57e705-7d30-4ed5-b1b9-aca3bedc50fe'::uuid, array['RHS (rhs.org.uk) — Iris virginica ''De Luxe''']::text[], 'Iris rizomatoso della famiglia delle Iridacee, originario delle paludi e delle rive dell''America settentrionale orientale, dove è chiamato iris blu meridionale. Alto fino a 90 cm, ha foglie strette, a volte rossastre alla base in primavera, e all''inizio dell''estate porta su steli scuri diversi fiori viola o lavanda, con i petali ricadenti segnati da una macchia gialla bordata di bianco. Vuole terreno umido o bagnato, profondo, ricco di humus e non calcareo, al sole o in mezz''ombra: è perfetto per i bordi degli stagni e i giardini palustri.', 'A rhizomatous perennial to 95cm in height, with narrow leaves, dark red in spring, becoming green with a purple tinge at the base, and straight, dark purple stems to 70cm bearing 6-8 small flowers. Standards are cupped, erect, violet. Falls are drooping, violet, with a yellow, white-edged signal', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, poco drenato", "terreno": "Argilloso, franco; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a lumache, limacce e tripidi; Malattie: può essere soggetto a virosi trasmesse dagli afidi, marciume batterico e muffa grigia', 'Rusticità: minime anche sotto i -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: in autunno si tolgono le foglie secche; gli steli sfioriti si possono tagliare dopo la fioritura', 'Propagazione: per divisione dei rizomi da metà estate a inizio autunno']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 103340'),
('1a72e861-85ba-5324-84da-59d3cc0a4e1c'::uuid, '202186a4-f7e8-4220-bfa7-2ce98fa82a01'::uuid, array['RHS (rhs.org.uk) — Leptospermum myrtifolium ''Silver Sheen''']::text[], 'Arbusto sempreverde della famiglia delle Mirtacee, originario dell''Australia sudorientale, dove cresce lungo i torrenti di montagna. Eretto e fitto, alto fino a 2 m, ha piccole foglie morbide e argentate su rametti rossastri e a metà estate si copre di fiori bianchi a cinque petali, simili a quelli del mirto. Vuole terreno ben drenato e mediamente fertile, sole o mezz''ombra, e sopporta il gelo leggero; si presta anche a essere allevato contro un muro.', 'An erect evergreen shrub, with small, softly hairy, silvery leaves on reddish shoots, and white flowers in mid summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto, raramente, ad armillaria', 'Rusticità: minime fino a -5 °C', 'Potatura: richiede pochi interventi: dopo la fioritura si spuntano i rami per tenerlo compatto e si tolgono quelli secchi o rovinati, senza tagliare nel legno vecchio', 'Propagazione: per seme a 13-16 °C in autunno o in primavera o per talee semilegnose con calore dal fondo in estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 103171'),
('16e9b466-000b-51b1-8b40-86b1650032f5'::uuid, '8bc872f2-9d42-4c3d-b71b-fe6baa36ab2f'::uuid, array['RHS (rhs.org.uk) — Lychnis × arkwrightii ''Vesuvius''']::text[], 'Perenne di breve vita della famiglia delle Cariofillacee, ibrido tra Lychnis chalcedonica e Lychnis × haageana. Forma cespi alti circa 45 cm di foglie ovali o lanceolate, leggermente pelose e fortemente sfumate di porpora bronzo, e all''inizio dell''estate porta su steli rigidi mazzetti di fiori a stella rosso arancio brillante, con i petali incisi, che risaltano sul fogliame scuro. Vuole terreno fertile, fresco ma ben drenato, e pieno sole, con un po'' d''ombra nelle ore più calde.', 'A short-lived perennial to 45cm high, with finely hairy, oval to lance-shaped green leaves strongly flushed with purple-bronze. Clusters of bright orange-red, star-shaped flowers with notched petals are borne on stiff, upright stems in early summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a limacce, afidi e sputacchine; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: a inizio stagione si cimano le punte per renderla più compatta; si tolgono i fiori appassiti per prolungare la fioritura e limitare la disseminazione', 'Propagazione: per seme, per divisione dei cespi o per talee basali in primavera; si risemina da sola, ma le piantine possono essere diverse']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 91996'),
('d62ce229-4dd5-5bf4-b743-84e407956450'::uuid, '7c2d48a3-f15b-4193-8161-36deb5e1c461'::uuid, array['RHS (rhs.org.uk) — Oxalis purpurea ''Ken Aslet''']::text[], 'Piccola acetosella bulbosa della famiglia delle Oxalidacee, originaria della provincia del Capo in Sudafrica. Forma tappeti bassi, sotto i 10 cm, di foglie trifogliate e vellutate, spesso porpora sulla pagina inferiore, e in autunno e in inverno porta fiori a imbuto appena sopra le foglie, rosa, porpora, bianchi o gialli secondo la varietà, che si aprono solo col sole. D''estate va in riposo e sparisce. Vuole terreno povero e ben drenato e una posizione soleggiata e riparata; nei climi freddi si coltiva in vaso al riparo.', 'A small mat-forming plant up to 10cm tall in flower, with felty, pale green, trefoil leaves covered with silvery hairs and  funnel-shaped, bright lemon-yellow flowers just above the leaves, in autumn, dormant in summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Sabbioso; pH acido, neutro, alcalino"}'::jsonb, 'perenne', array['Parassiti: all''aperto può essere soggetta a lumache e limacce; Malattie: può essere soggetta a ruggine', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0-0.1m', 'Potatura: non richiede potatura', 'Propagazione: per seme o per divisione']::text[], 'bozza', true, 'bulbosa', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 82724'),
('07a76997-33b3-5877-9d0f-8317fc6bd633'::uuid, '3d27e9db-88c1-430a-a9c0-09c551104595'::uuid, array['RHS (rhs.org.uk) — Cissus rhomboidea']::text[], 'Rampicante sempreverde della famiglia delle Vitacee, originario delle foreste del Sudafrica, che si aggrappa con i viticci e raggiunge i 3 m. Ha foglie lucide divise in tre foglioline ovali e dentate, verde scuro, e porta fiori insignificanti a cui possono seguire bacche nero bluastre. Coltivato da tempo come pianta d''appartamento con il nome di Cissus rhomboidea, è resistente e paziente: vuole luce intensa ma filtrata, annaffiature moderate e d''inverno non deve scendere sotto i 5 °C.', 'An evergreen tendril climber to 3m, with glossy green leaves composed of 3 broadly ovate leaflets. Insignificant flowers may be followed by blue-black berries', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Franco; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a ragnetto rosso, mosca bianca e cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 5 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 0.1-0.5m', 'Potatura: si accorcia quando serve per contenerlo, tagliando i fusti troppo lunghi o che escono dal supporto', 'Propagazione: per talee erbacee o legnose in estate']::text[], 'bozza', true, 'rampicante', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 212848'),
('02bbae68-5f3e-5293-9f90-0b67d436d80e'::uuid, '5ac70761-7b92-4452-bd30-828477ca5d92'::uuid, array['RHS (rhs.org.uk) — Santolina virens']::text[], 'Suffrutice sempreverde e aromatico della famiglia delle Asteracee, originario della Spagna e del Portogallo, considerato da alcuni autori una forma di Santolina rosmarinifolia. Forma cuscini larghi e bassi, fino a 60 cm, di foglie verde brillante finemente divise, che strofinate profumano di resina. A metà estate porta su lunghi steli capolini a bottone giallo vivo, larghi circa 2 cm. Ama il caldo, il sole pieno e i terreni sciolti e ben drenati: è perfetta per le bordure basse e i giardini di ghiaia, ma con gli anni tende a spogliarsi.', 'A spreading evergreen shrub to 60cm tall, with finely dissected green leaves and bright yellow flower heads 2cm wide in mid summer', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetta ad armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: dopo la fioritura si accorcia tutta la pianta tagliando gli steli fioriti, per mantenerla densa e compatta; in primavera si possono spuntare i fusti, senza tagliare nel legno vecchio', 'Propagazione: per talee semilegnose a fine estate, con calore dal fondo']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 16434'),
('bfa7cc18-6705-5acc-9bea-2e91f5fd6673'::uuid, '2f1a0839-b2c7-4250-a3cf-b4fa4744a447'::uuid, array['RHS (rhs.org.uk) — Scabiosa ochroleuca']::text[], 'Perenne erbacea della famiglia delle Caprifoliacee, diffusa dall''Europa centrale e orientale fino all''Asia, presente anche nei prati aridi dell''Italia settentrionale. Forma cespi leggeri e ariosi di foglie strette, dentate e grigio-verdi, e in estate porta su steli sottili e ramificati numerosi capolini giallo pallido, a cuscinetto, come in tutte le vedovine. Ama il pieno sole e i terreni fertili e ben drenati, meglio se calcarei, ed è molto visitata da api e farfalle.', 'A clump-forming herbaceous perennial of dainty character. Leaves are narrow, oval, toothed and grey-green. In summer it bears branching, wiry stems of many pale yellow flowers in the typical petalled, pincushion style of this genus', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: in autunno si tagliano gli steli alla base', 'Propagazione: per seme in autunno o per talee basali in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 81379'),
('cb7fd2f4-5cbd-526d-8077-a6d99a7c150c'::uuid, '413ed707-5ce9-4b81-b438-38e45a3cf49a'::uuid, array['RHS (rhs.org.uk) — Sisyrinchium bermudiana']::text[], 'Piccola perenne semisempreverde della famiglia delle Iridacee, che forma ciuffi alti fino a 50 cm di foglie strette, verde scuro, simili a quelle di un''erba. Per tutta l''estate porta su steli eretti fiori a stella larghi circa 2 cm, di un azzurro profondo con la gola gialla, che si aprono col sole. Vuole terreno povero o mediamente fertile, ben drenato, e pieno sole, e teme l''umidità invernale. Si risemina con grande facilità e può diventare invadente.', 'A semi-evergreen perennial to 50cm, producing clumps of narrow, dark green, grass-like foliage and upright stems bearing deep blue, yellow-throated flowers 2cm across all summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetta a marciume radicale', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura; si tolgono gli steli sfioriti se non si vuole che si risemini', 'Propagazione: per seme o per divisione in primavera; si risemina da sola']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 17384'),
('c3ebecad-6e19-5ca7-bafd-6cd2d6a9f7e2'::uuid, 'b58350b9-9022-4963-a629-1e994d1553e0'::uuid, array['RHS (rhs.org.uk) — Skimmia × foremanii']::text[], 'Arbusto sempreverde della famiglia delle Rutacee, ibrido di Skimmia japonica, eretto e fitto, alto e largo fino a 1,5 m, con foglie larghe e ovali di un verde intenso. In primavera porta mazzetti densi di piccoli fiori bianchi a stella, profumati, seguiti da bacche rotonde rosso brillante che restano a lungo sui rami. Ama l''ombra e il terreno fresco e ricco di humus; al sole o in terreno povero e secco le foglie ingialliscono. Sopporta bene lo smog e una certa trascuratezza.', 'An upright, evergreen, dense shrub, to 1.5m tall and wide, with broadly-oval, rich green leaves. Dense clusters of small, star-shaped, white spring flowers are followed by brilliant red spherical fruit', 'it', '{"luce": "Ombra piena, pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, franco; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a cocciniglie e, in vaso, a oziorrinco; Malattie: può essere soggetto a Phytophthora e armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 1-1.5m, diffusione 1-1.5m', 'Potatura: richiede pochi interventi: dopo la fioritura si accorciano i rami troppo lunghi e si tolgono quelli secchi o rovinati', 'Propagazione: per talee semilegnose a fine estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 17400'),
('72489579-7070-5a4a-807c-5eb2f9111d7d'::uuid, 'd0817fb9-2de6-4f46-9be9-c38ea28c33e6'::uuid, array['RHS (rhs.org.uk) — Spiraea × billardii ''Triumphans''']::text[], 'Arbusto deciduo della famiglia delle Rosacee, ibrido tra Spiraea douglasii e Spiraea salicifolia, vigoroso e pollonifero, alto e largo fino a 2,5 m. Forma un fitto boschetto di steli sottili con foglie oblunghe verde scuro e, da metà a fine estate, porta in cima ai rami pannocchie coniche di minuscoli fiori rosa porpora, piumose e molto amate dalle api. Facile e adattabile, cresce in quasi tutti i terreni freschi e sopporta condizioni difficili, ma con il tempo tende ad allargarsi.', 'A vigorous suckering deciduous shrub forming a thicket of slender stems bearing dark-green, oblong leaves and tiny purplish-pink flowers in conical panicles in mid or late summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie, ma può essere soggetto ad armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 1.5-2.5m, diffusione 1.5-2.5m', 'Potatura: a fine inverno si accorciano i rami che hanno fiorito l''anno prima e ogni anno si toglie alla base qualche ramo vecchio; gli esemplari troppo cresciuti si possono ringiovanire con un taglio drastico', 'Propagazione: per talee erbacee in estate o per divisione in autunno o in primavera']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 94157'),
('6073bc2c-60a5-52a1-81da-00d3b93b87d0'::uuid, 'fe8e4333-fbba-497c-910a-e9f520684188'::uuid, array['RHS (rhs.org.uk) — ×Halimiocistus wintonensis']::text[], 'Arbusto nano sempreverde della famiglia delle Cistacee, ibrido tra un cisto e un halimium nato in vivaio all''inizio del Novecento. Basso e allargato, ha foglie strette grigio-verdi e tra la tarda primavera e l''inizio dell''estate porta fiori bianchi larghi 5 cm, con ogni petalo segnato da una fascia cremisi sopra la base gialla, che durano un solo giorno ma si rinnovano a lungo. Vuole terreno povero, sabbioso e ben drenato, pieno sole e riparo dai venti freddi.', 'A spreading, bushy dwarf evergreen shrub with narrowly elliptic, grey-green leaves. Flowers 5cm wide, white, each petal with a crimson zone above the yellow base, opening in late spring and early summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.5-1m', 'Potatura: di rado ha bisogno di potatura: dopo la fioritura si possono spuntare i rami per tenerlo compatto, senza tagliare nel legno vecchio', 'Propagazione: per talee erbacee dalla tarda primavera all''inizio dell''estate o semilegnose da metà estate a fine inverno']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 23/11/2026, schede nuove; pagina RHS 92451');
do $$ declare n int; begin
